  <script>
    const canvas = document.getElementById('pendulumCanvas');
    const ctx = canvas.getContext('2d');
    const initialAngleInput = document.getElementById('initialAngle');
    const releaseButton = document.getElementById('releaseButton');
    const gravity = 9.81; // m/s^2
    const length = 100; // pixels
    let angle = 0;
    let speed = 0;
    let released = false;

    releaseButton.addEventListener('click', () => {
      angle = toRadians(initialAngleInput.value);
      speed = 0;
      released = true;
    });

    function animate() {
      if (released) {
        angle += (0 - angle) * 0.1; // dampening
        speed += gravity * Math.sin(angle) / length;
        if (Math.abs(speed) < 0.1 && Math.abs(angle) < 0.1) {
          released = false;
        }
        ctx.clearRect(0, 0, canvas.width, canvas.height);
        ctx.beginPath();
        ctx.arc(canvas.width / 2, canvas.height / 2, length / 2, 0, 2 * Math.PI);
        ctx.moveTo(canvas.width / 2, canvas.height / 2);
        ctx.lineTo(canvas.width / 2 + Math.sin(angle) * length / 2, canvas.height / 2 - Math.cos(angle) * length / 2);
        ctx.stroke();
        requestAnimationFrame(animate);
      }
    }

    animate();

    function toRadians(degrees) {
      return degrees * Math.PI / 180;
    }
  </script>
</body>
</html>
```

