func handler(ctx context.Context) (interface{}, error) {
	sess, err := session.NewSession(&aws.Config{Region: aws.String("your-region")}, nil)
	if err != nil {
		return nil, err
	}
	ec2Svc := ec2.New(sess)

	// Filter EBS Snapshots by tag "backup_type"
	snapshots, err := ec2Svc.DescribeSnapshots(&ec2.DescribeSnapshotsInput{
		Filters: []*ec2.Filter{
			{
				Name: aws.String("tag:backup_type"),
				Values: []*string{
					aws.String("monthly"),
					aws.String("daily"),
					aws.String("weekly"),
					aws.String("yearly"),
				},
			},
		},
	})
	if err != nil {
		return nil, err
	}

	// Create a map to store snapshots by "backup_type"
	snapshotMap := map[string][]*ec2.Snapshot{}
	for _, snapshot := range snapshots.Snapshots {
		tag := snapshot.Tags.Find(func(tag *ec2.Tag) bool { return *tag.Key == "backup_type" })
		if tag != nil {
			snapshotMap[*tag.Value] = append(snapshotMap[*tag.Value], snapshot)
		}
	}

	// Delete excess snapshots based on retention policies
	for tag, snapshots := range snapshotMap {
		switch *tag {
		case "monthly":
			// Keep the last 14 monthly snapshots
			keepSnapshots := snapshots[:len(snapshots)-14]
			ec2Svc.DeleteSnapshots(&ec2.DeleteSnapshotsInput{
				SnapshotIds: snapshots[len(snapshots)-14:].Ids(),
			})
		case "daily":
			// Keep the last 10 daily snapshots
			keepSnapshots := snapshots[:len(snapshots)-10]
			ec2Svc.DeleteSnapshots(&ec2.DeleteSnapshotsInput{
				SnapshotIds: snapshots[len(snapshots)-10:].Ids(),
			})
		case "weekly":
			// Keep the last 4 weekly snapshots
			keepSnapshots := snapshots[:len(snapshots)-4]
			ec2Svc.DeleteSnapshots(&ec2.DeleteSnapshotsInput{
				SnapshotIds: snapshots[len(snapshots)-4:].Ids(),
			})
		case "yearly":
			// Keep only the last yearly snapshot
			keepSnapshots := []*ec2.Snapshot{snapshots[0]}
			ec2Svc.DeleteSnapshots(&ec2.DeleteSnapshotsInput{
				SnapshotIds: snapshots[1:].Ids(),
